        }

        getHint(state, results) {
            if (!results) return null;
            var day = state.currentPeriod;
            var ds = state.domainState;

            if (results.changeoverCost > 200) {
                return window.mySimulation.t('hint_changeover');
            }
            if (day === 2 && ds.orderB_remaining > 0 && state.decisions.product === 'work') {
                return window.mySimulation.t('hint_orderB_urgent');
            }
            if (day === 3 && ds.orderC_remaining > 0 && state.decisions.product === 'school') {
                return window.mySimulation.t('hint_orderC_urgent');
            }
            if (results.queueSewing > 200) {
                return window.mySimulation.t('hint_bottleneck_queue');
            }
            if (results.profit < 0) {
                return window.mySimulation.t('hint_loss');
            }
            return null;
        }

